import{_ as t,o as a,c as r,a0 as o}from"./chunks/framework.BQGW-Zpy.js";const p=JSON.parse('{"title":"The Trust Layer. Hedera","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/trust-layer.md","filePath":"architecture/trust-layer.md"}'),n={name:"architecture/trust-layer.md"};function s(i,e,h,c,d,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="the-trust-layer-hedera" tabindex="-1">The Trust Layer. Hedera <a class="header-anchor" href="#the-trust-layer-hedera" aria-label="Permalink to &quot;The Trust Layer. Hedera&quot;">​</a></h1><h2 id="what-gets-anchored" tabindex="-1">What gets anchored <a class="header-anchor" href="#what-gets-anchored" aria-label="Permalink to &quot;What gets anchored&quot;">​</a></h2><p>Four kinds of record, through two mechanisms (<code>anchorRecord</code> in <code>anchor.mjs</code> for the first three; the Hedera Schedule Service for the fourth):</p><table tabindex="0"><thead><tr><th>Record</th><th>Proves</th></tr></thead><tbody><tr><td><strong>Compliance</strong></td><td>A licensed party&#39;s KYC/AML check passed, at a specific moment</td></tr><tr><td><strong>Quote</strong></td><td>The FX rate and fee shown to the sender before settlement, so it can&#39;t be quietly changed before payout</td></tr><tr><td><strong>Routing decision</strong></td><td>Which chain a transfer settled on, and why, auditable, not just asserted</td></tr><tr><td><strong>Completion</strong></td><td>Both the source-side and destination-side partner independently confirm the transfer finished, not just our own backend&#39;s say-so</td></tr></tbody></table><h2 id="what-never-goes-on-chain" tabindex="-1">What never goes on-chain <a class="header-anchor" href="#what-never-goes-on-chain" aria-label="Permalink to &quot;What never goes on-chain&quot;">​</a></h2><p>Only a SHA-256 hash of a canonical JSON record, plus a pseudonymous reference (HMAC&#39;d, not a plain hash, see <a href="./../legal/compliance-data.html">Compliance Data &amp; Privacy</a> for why that distinction matters). No names, no IBANs, no amounts, no documents.</p><h2 id="why-a-narrow-trust-surface-matters" tabindex="-1">Why a narrow trust surface matters <a class="header-anchor" href="#why-a-narrow-trust-surface-matters" aria-label="Permalink to &quot;Why a narrow trust surface matters&quot;">​</a></h2><p>Hedera never sees the underlying record and holds no party&#39;s signing key. It only supplies <strong>ordering and a consensus timestamp</strong>. That means:</p><ul><li>Even a compromised or colluding set of Hedera nodes could not forge a compliance record, they hold no one&#39;s key.</li><li>The only thing anyone needs to trust Hedera for is: <em>this hash existed at this exact moment, in this order.</em></li><li>Because trust rests on the hash rather than on Hedera specifically, the anchor is portable in principle, nothing here is permanently wedded to one ledger surviving forever.</li></ul><h2 id="the-completion-anchor-gated-by-two-parties-not-one" tabindex="-1">The completion anchor: gated by two parties, not one <a class="header-anchor" href="#the-completion-anchor-gated-by-two-parties-not-one" aria-label="Permalink to &quot;The completion anchor: gated by two parties, not one&quot;">​</a></h2><p>The first three records are anchored the moment our backend decides they&#39;re true. The completion record is different by design: it uses the <strong>Hedera Schedule Service (HSS)</strong> so that the &quot;transfer is fully complete&quot; message only reaches HCS once <strong>both</strong> the source-side and destination-side partner have separately signed off.</p><p>Mechanically:</p><ol><li>A <code>ScheduleCreateTransaction</code> wraps the completion message. It sits pending on Hedera, executing nothing yet.</li><li>The message can only be submitted by a <strong>2-of-2 threshold key</strong> held jointly by the two partners, a <code>KeyList</code> requiring both signatures, never one held by us.</li><li>The moment the second <code>ScheduleSignTransaction</code> lands, Hedera&#39;s own consensus executes the submission automatically, no code of ours triggers that execution.</li><li>If neither signature arrives within the schedule&#39;s expiry window, it simply never executes. No silent partial state, no fabricated success.</li></ol><p>The two-party requirement is enforced at the protocol level: the HCS topic the completion message is written to has its <strong>submit key set to that same 2-of-2 <code>KeyList</code></strong>, not to our operator key. That&#39;s what makes the gate real rather than cosmetic, our own signature as transaction payer cannot satisfy it; only the two partners together can.</p><h2 id="the-intermediary-settlement-account-same-2-of-2-principle-for-funds" tabindex="-1">The intermediary settlement account: same 2-of-2 principle, for funds <a class="header-anchor" href="#the-intermediary-settlement-account-same-2-of-2-principle-for-funds" aria-label="Permalink to &quot;The intermediary settlement account: same 2-of-2 principle, for funds&quot;">​</a></h2><p>Stablecoin from the source-side partner lands in an intermediary Hedera account before the destination-side partner pulls it for payout. That account&#39;s key is the same 2-of-2 <code>KeyList</code>, one key per partner. Neither partner alone, and critically, <strong>we are not one of the two keys</strong>, can move funds out of it unilaterally.</p><h2 id="reading-it-back" tabindex="-1">Reading it back <a class="header-anchor" href="#reading-it-back" aria-label="Permalink to &quot;Reading it back&quot;">​</a></h2><p>Verification never touches our API. Anyone, a regulator, an auditor, a teammate, can query a <strong>public Hedera Mirror Node</strong> directly, recompute the hash of the record as it exists now, and compare. See <a href="./../reference/modules.html#verifymjs"><code>verify.mjs</code></a>.</p><p>For the fuller case on why this specific property, public observability without exposing personal data, is valuable to regulators beyond just this platform, see <a href="./../legal/regulator-oversight.html">A Regulator-Facing Case for Public Anchoring</a>.</p>',19)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
